#include <iostream>
using std::cin;
using std::cout;
#include <vector>
using std::vector;
#include <algorithm>
using std::sort;
using std::max;
using std::min;

typedef long long int ll;

#include <atcoder/segtree>
using atcoder::segtree;

ll n, q;
vector<ll> a, b;

const ll MAX_A = 1'000'006LL;

struct Seg {
	ll sum;
	ll cnt1;
	ll cnt2;
};
const Seg unity = {0, 0, 0};

Seg seg_op (Seg l, Seg r) {
	return {
		l.sum  + r.sum,
		l.cnt1 + r.cnt1,
		l.cnt2 + r.cnt2
	};
}
Seg seg_e () {
	return unity;
}

ll f_thres = 0;
bool f_lower (Seg s) {
	return (s.cnt1 + s.cnt2) < f_thres;
}
bool f_no2 (Seg s) {
	return s.cnt2 <= 0;
}


void solve () {
	ll whole1 = 0, whole2 = 0, wholesum = 0;
	vector<Seg> leaf(MAX_A + 1, unity);
	segtree<Seg, seg_op, seg_e> seg(MAX_A + 1);
	for (ll i = 0; i < n; i++) {
		wholesum += a[i];
		if (b[i] == 1) {
			leaf[a[i]].sum += a[i];
			leaf[a[i]].cnt1 += 1;
			whole1++;
		} else {
			leaf[a[i]].sum += a[i];
			leaf[a[i]].cnt2 += 1;
			whole2++;
		}
		seg.set(a[i], leaf[a[i]]);
	}

	for (ll qi = 0; qi < q; qi++) {
		ll w, x, y;
		cin >> w >> x >> y;
		--w;

		wholesum -= a[w];
		if (b[w] == 1) {
			leaf[a[w]].sum  -= a[w];
			leaf[a[w]].cnt1 -= 1;
			whole1--;
		} else {
			leaf[a[w]].sum  -= a[w];
			leaf[a[w]].cnt2 -= 1;
			whole2--;
		}
		seg.set(a[w], leaf[a[w]]);

		a[w] = x;
		b[w] = y;
		wholesum += a[w];
		if (b[w] == 1) {
			leaf[a[w]].sum  += a[w];
			leaf[a[w]].cnt1 += 1;
			whole1++;
		} else {
			leaf[a[w]].sum  += a[w];
			leaf[a[w]].cnt2 += 1;
			whole2++;
		}
		seg.set(a[w], leaf[a[w]]);

		ll minus;
		if (whole2 == 0) {
			minus = wholesum;
		} else {
			ll z = max(1LL, whole1);

			f_thres = z;
			ll ri = seg.max_right<f_lower>(0); // z-smallest (combining type1/2) is ri

			Seg s = seg.prod(0, ri+1);
			if (s.cnt2 > 0) {
				minus = s.sum - ri * (s.cnt1 + s.cnt2 - z);
			} else {
				ll bi = seg.max_right<f_no2>(0); // smallest type2 is bi
				minus = s.sum - ri * (s.cnt1 + s.cnt2 - z + 1) + bi;
			}
		}

		ll ans = wholesum * 2 - minus;
		cout << ans << "\n";

	}
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> n >> q;
	a.resize(n);
	b.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> a[i] >> b[i];
	}

	solve();

	return 0;
}
